fn evaluate(j:J)->J {match j["kind"].as_str().unwrap(){
 "buffer_clone"=>{let original=UnifiedLogBuffer::default();let copied=original.clone();let shared=std::sync::Arc::ptr_eq(&original.entries,&copied.entries);copied.entries.lock().unwrap().push(UnifiedLogEntry{timestamp:UNIX_EPOCH,user_identifier:None,trace_chain:vec![],payload:LogPayload::Info(InfoLogEntry{message:"shared".into()})});let source_after_push=original.entries.lock().unwrap().len();original.entries.lock().unwrap().clear();let clone_after_clear=copied.entries.lock().unwrap().len();json!({"shares_entries":shared,"source_after_clone_push":source_after_push,"clone_after_source_clear":clone_after_clear})},
 "options"=>{let operation=[SqlLogOperation::Select,SqlLogOperation::Insert,SqlLogOperation::Update,SqlLogOperation::Delete,SqlLogOperation::Recover][j["operation"].as_u64().unwrap() as usize];let options=[SqlLogOptions::disabled(),SqlLogOptions::select_only(),SqlLogOptions::mutation_only(),SqlLogOptions::all()][j["mode"].as_u64().unwrap() as usize];json!({"operation":formatted(&operation),"select":operation.is_select(),"mutation":operation.is_mutation(),"options":formatted(&options),"default":formatted(&SqlLogOptions::default()),"enabled":options.enabled_for(operation)})},
 "level"=>{let fallback=[LogLevel::Silent,LogLevel::Summary,LogLevel::Full,LogLevel::FullWithPayload][j["fallback"].as_u64().unwrap() as usize];let value=LogLevel::parse(j["text"].as_str().unwrap(),fallback);json!({"debug":formatted(&value),"clone_equal":value==value.clone()})},
 "entries"=>{let sql=entry(&j);let mut other=sql.clone();other.result_summary.push('!');let info=InfoLogEntry{message:"info🧊\0message".into()};let payload=if j["info"]==true{LogPayload::Info(info.clone())}else{LogPayload::Sql(sql.clone())};let unified=UnifiedLogEntry{timestamp:time(&j["start"]),user_identifier:text(&j["optional"]),trace_chain:sql.trace_path.clone(),payload:payload.clone()};let mut changed=unified.clone();changed.trace_chain.clear();json!({"sql":formatted(&sql),"sql_clone":formatted(&sql.clone()),"sql_clone_equal":sql==sql.clone(),"sql_changed_equal":sql==other,"parameter_count":sql.parameter_count(),"info":formatted(&info),"payload":formatted(&payload),"payload_clone_equal":payload==payload.clone(),"unified":formatted(&unified),"unified_clone":formatted(&unified.clone()),"unified_clone_equal":unified==unified.clone(),"unified_changed_equal":unified==changed})},_=>panic!("unknown log model")}}
